DO $$ DECLARE def text; fn text;BEGIN FOREACH fn IN ARRAY ARRAY['public.smart_alert_save_settings(uuid,jsonb)','public.smart_alert_toggle_ask(uuid,uuid,boolean)','public.smart_alert_action(uuid,uuid,text,jsonb)'] LOOP SELECT pg_get_functiondef(fn::regprocedure) INTO def;def:=replace(def,'''owner'',''admin'',''manager''','''owner'',''admin'',''manager'',''tenant_admin'',''platform_admin''');EXECUTE def;END LOOP;END $$;
CREATE UNIQUE INDEX smart_alert_summary_active_key ON public.alert_events(tenant_id,kind,coalesce(venue_id,'00000000-0000-0000-0000-000000000000'::uuid),subject) WHERE kind IS NOT NULL AND status IN ('open','muted','summary');
CREATE OR REPLACE FUNCTION public.smart_alert_limit_open() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.kind IS NOT NULL AND NEW.status='open' THEN PERFORM pg_advisory_xact_lock(hashtext('smart-alert:'||NEW.tenant_id::text));IF (SELECT count(*) FROM alert_events WHERE tenant_id=NEW.tenant_id AND status='open' AND kind IS NOT NULL AND id<>NEW.id)>=10 THEN NEW.status:='summary';END IF;END IF;RETURN NEW;END $$;
CREATE TRIGGER smart_alert_open_limit BEFORE INSERT OR UPDATE OF status ON public.alert_events FOR EACH ROW EXECUTE FUNCTION public.smart_alert_limit_open();
COMMENT ON TABLE public.alert_rules IS 'DEPRECATED: read-only legacy rules; confirmed conversational asks use alert_asks.';